/**
 * Cloudflare Worker for Frydge recipe share links.
 *
 * Routes to bind in Cloudflare:
 *   frydge2.com/.well-known/apple-app-site-association
 *   frydge2.com/recipe/*
 *
 * Bindings used below:
 *   RECIPE_SHARES: KV namespace storing recipe metadata by recipe id
 *   RECIPE_IMAGES: KV namespace storing JPEG preview image base64 by recipe id
 *
 * KV value shape:
 * {
 *   "title": "Chicken Pasta",
 *   "time": "35m",
 *   "imageURL": "https://frydge2.com/images/<recipe-id>.jpg",
 *   "description": "35m recipe from Frydge"
 * }
 */

const TEAM_ID = "A2H3YQ5U79";
const BUNDLE_ID = "Clark-Online.Recipes";
const DOMAIN = "https://frydge2.com";
const UPLOAD_KEY = "frydge2webrecipes";
// Largest recipe body (JSON) accepted alongside a share; keeps KV values small.
const MAX_RECIPE_PAYLOAD_BYTES = 256 * 1024;
// Set to the App Store listing once live, e.g. "https://apps.apple.com/app/id123456789".
const APP_STORE_URL = "";
const DEFAULT_IMAGE_URL = `${DOMAIN}/images/default-recipe.svg`;
const PREVIEW_USER_AGENT_PATTERN = /(bot|crawler|spider|preview|facebookexternalhit|facebot|twitterbot|slackbot|discordbot|whatsapp|telegram|linkedinbot|pinterest|applebot|messages|google|bingbot)/i;

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (url.pathname === "/.well-known/apple-developer-merchantid-domain-association.txt") {
      return new Response(APPLE_MERCHANT_DOMAIN_ASSOCIATION, {
        status: 200,
        headers: {
          "Content-Type": "text/plain; charset=utf-8",
          "Cache-Control": "public, max-age=3600",
          "Access-Control-Allow-Origin": "*"
        }
      });
    }



    if (request.method === "OPTIONS") {
      return corsResponse(null, 204);
    }

    if (url.pathname === "/.well-known/apple-app-site-association") {
      return jsonResponse(appleAppSiteAssociation());
    }

    if (url.pathname === "/api/share-recipe" && request.method === "POST") {
      return saveRecipeShare(request, env);
    }

    const payloadMatch = url.pathname.match(/^\/api\/recipe\/([^/]+)$/);
    if (payloadMatch && request.method === "GET") {
      return recipePayloadResponse(decodeURIComponent(payloadMatch[1]), env);
    }

    if (url.pathname === "/images/default-recipe.svg") {
      return defaultRecipeImageResponse();
    }

    const imageMatch = url.pathname.match(/^\/images\/([^/]+)\.jpg$/);
    if (imageMatch) {
      return recipeImageResponse(imageMatch[1], env);
    }

    const recipeMatch = url.pathname.match(/^\/recipe\/([^/]+)$/);
    if (recipeMatch) {
      return recipePreviewResponse(request, recipeMatch[1], env);
    }

    return new Response("Not found", { status: 404 });
  }
};

async function saveRecipeShare(request, env) {
  if (!env.RECIPE_SHARES || !env.RECIPE_IMAGES) {
    return jsonResponse({ error: "Missing RECIPE_SHARES or RECIPE_IMAGES binding" }, 500);
  }

  let body;
  try {
    body = await request.json();
  } catch {
    return jsonResponse({ error: "Invalid JSON body" }, 400);
  }

  const id = cleanId(body.id);
  const title = typeof body.title === "string" ? body.title.trim() : "";
  const description = typeof body.description === "string" ? body.description : "Open in Frydge";
  const time = typeof body.time === "string" ? body.time : null;
  const imageBase64 = typeof body.imageBase64 === "string" ? body.imageBase64 : "";
  const imageContentType = body.imageContentType === "image/jpeg" ? "image/jpeg" : null;
  const imageWidth = Number.isInteger(body.imageWidth) && body.imageWidth > 0 ? body.imageWidth : 512;
  const imageHeight = Number.isInteger(body.imageHeight) && body.imageHeight > 0 ? body.imageHeight : 512;
  const headerUploadKey = request.headers.get("X-Frydge-Upload-Key") || "";
  const bodyUploadKey = typeof body.uploadKey === "string" ? body.uploadKey : "";
  const uploadKey = headerUploadKey || bodyUploadKey;

  if (uploadKey !== UPLOAD_KEY) {
    return jsonResponse({ error: "Invalid upload key" }, 401);
  }

  if (!id || !title || !imageContentType) {
    return jsonResponse({ error: "Missing id, title, or imageContentType" }, 400);
  }

  // Full recipe body so recipients without the recipe can import it, and so
  // the web page can show ingredients + method to people without the app.
  const recipe = sanitizeRecipePayload(body.recipe);

  const imageURL = imageBase64 ? `${DOMAIN}/images/${encodeURIComponent(id)}.jpg` : DEFAULT_IMAGE_URL;
  const shareURL = `${DOMAIN}/recipe/${encodeURIComponent(id)}`;

  if (imageBase64) {
    await env.RECIPE_IMAGES.put(id, imageBase64, {
      metadata: { contentType: imageContentType }
    });
  }

  const metadata = {
    title,
    time,
    description,
    imageURL,
    imageWidth: imageBase64 ? imageWidth : 1200,
    imageHeight: imageBase64 ? imageHeight : 630,
    recipe,
    updatedAt: new Date().toISOString()
  };

  await env.RECIPE_SHARES.put(id, JSON.stringify(metadata));

  return jsonResponse({ ok: true, id, recipeId: id, shareURL, imageURL, hasRecipe: Boolean(recipe) }, 200, "no-store");
}

/**
 * Bounds the recipe body the app uploads. Field shapes mirror the app's
 * CloudRecipe Codable keys; unknown keys are dropped and the whole thing is
 * rejected if it exceeds MAX_RECIPE_PAYLOAD_BYTES.
 */
function sanitizeRecipePayload(raw) {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) {
    return null;
  }

  const str = (value, max) => (typeof value === "string" ? value.slice(0, max) : undefined);
  const strList = (value, maxItems, maxLength) =>
    Array.isArray(value)
      ? value.filter(item => typeof item === "string").slice(0, maxItems).map(item => item.slice(0, maxLength))
      : undefined;

  const recipe = {
    id: str(raw.id, 160),
    name: str(raw.name, 300),
    serves: str(raw.serves, 60),
    ingredients: strList(raw.ingredients, 200, 500),
    pan: str(raw.pan, 200),
    instructions: str(raw.instructions, 20000),
    steps: Array.isArray(raw.steps) ? raw.steps.filter(step => step && typeof step === "object").slice(0, 200) : undefined,
    location: str(raw.location, 60),
    dietaryTags: strList(raw.dietaryTags, 40, 60),
    ingredientsMetaJSON: str(raw.ingredientsMetaJSON, 20000),
    imageSourceURL: str(raw.imageSourceURL, 2000),
    imageCredit: raw.imageCredit && typeof raw.imageCredit === "object" && !Array.isArray(raw.imageCredit) ? raw.imageCredit : undefined,
    authorName: str(raw.authorName, 120),
    creatorRecordName: str(raw.creatorRecordName, 200),
    creationDate: str(raw.creationDate, 40),
    modificationDate: str(raw.modificationDate, 40)
  };

  for (const key of Object.keys(recipe)) {
    if (recipe[key] === undefined) {
      delete recipe[key];
    }
  }

  if (!recipe.name) {
    return null;
  }

  if (JSON.stringify(recipe).length > MAX_RECIPE_PAYLOAD_BYTES) {
    return null;
  }

  return recipe;
}

function appleAppSiteAssociation() {
  return {
    applinks: {
      apps: [],
      details: [
        {
          appIDs: [`${TEAM_ID}.${BUNDLE_ID}`],
          components: [
            {
              "/": "/recipe/*",
              comment: "Recipe universal links"
            }
          ]
        }
      ]
    }
  };
}

/** JSON body the app fetches when it receives a link for a recipe it doesn't have. */
async function recipePayloadResponse(recipeId, env) {
  const cleanKey = cleanId(recipeId);
  if (!cleanKey) {
    return jsonResponse({ error: "Invalid recipe id" }, 400);
  }

  const share = await loadRecipeShare(cleanKey, env);
  if (!share) {
    return jsonResponse({ error: "Not found" }, 404, "no-store");
  }

  return jsonResponse(
    {
      id: cleanKey,
      title: share.title || null,
      description: share.description || null,
      time: share.time || null,
      imageURL: share.imageURL || null,
      updatedAt: share.updatedAt || null,
      recipe: share.recipe || null
    },
    200,
    "public, max-age=60"
  );
}

async function recipePreviewResponse(request, recipeId, env) {
  const share = await loadRecipeShare(recipeId, env);
  const title = share?.title || "Frydge Recipe";
  const description = share?.description || [share?.time, "Open in Frydge"].filter(Boolean).join(" · ") || "Open in Frydge";
  const pageURL = `${DOMAIN}/recipe/${encodeURIComponent(recipeId)}`;
  const imageURL = share?.imageURL || DEFAULT_IMAGE_URL;
  const imageWidth = share?.imageWidth || 1200;
  const imageHeight = share?.imageHeight || 630;
  const appURL = `frydge://recipe/${encodeURIComponent(recipeId)}`;
  const recipe = share?.recipe || null;

  const html = recipePageHTML({ title, description, pageURL, imageURL, imageWidth, imageHeight, appURL, recipe });

  // Crawlers can cache for longer; people should see edits quickly.
  const maxAge = shouldServeRichPreview(request) ? 300 : 60;
  return new Response(html, {
    headers: {
      "content-type": "text/html; charset=utf-8",
      "cache-control": `public, max-age=${maxAge}`
    }
  });
}

/**
 * One page for both link-preview crawlers (Open Graph tags) and people
 * (full recipe + Open in Frydge). People who have the app normally never
 * land here because the universal link opens the app directly, so this
 * page deliberately does not auto-redirect to the custom scheme — that
 * only produces a "cannot open page" error for visitors without the app.
 */
function recipePageHTML({ title, description, pageURL, imageURL, imageWidth, imageHeight, appURL, recipe }) {
  const ingredients = Array.isArray(recipe?.ingredients) ? recipe.ingredients : [];
  const steps = Array.isArray(recipe?.steps) ? recipe.steps : [];
  const serves = typeof recipe?.serves === "string" && recipe.serves.trim() ? recipe.serves.trim() : null;
  const author = typeof recipe?.authorName === "string" && recipe.authorName.trim() ? recipe.authorName.trim() : null;
  const tags = Array.isArray(recipe?.dietaryTags) ? recipe.dietaryTags : [];
  const instructions = typeof recipe?.instructions === "string" ? recipe.instructions.trim() : "";

  const metaBits = [];
  if (serves) metaBits.push(`Serves ${escapeHTML(serves)}`);
  if (ingredients.length) metaBits.push(`${ingredients.length} ingredients`);
  if (author) metaBits.push(`By ${escapeHTML(author)}`);

  const ingredientsHTML = ingredients.length
    ? `<section><h2>Ingredients</h2><ul>${ingredients.map(item => `<li>${escapeHTML(item)}</li>`).join("")}</ul></section>`
    : "";

  const stepsHTML = steps.length
    ? `<section><h2>Method</h2><ol>${steps
        .map(step => {
          const text = typeof step?.text === "string" ? step.text : "";
          const extras = [];
          if (Number.isFinite(step?.timerSeconds) && step.timerSeconds > 0) extras.push(formatDuration(step.timerSeconds));
          if (Number.isFinite(step?.temperatureValue) && step.temperatureValue > 0) {
            extras.push(`${step.temperatureValue}${typeof step.temperatureUnit === "string" ? step.temperatureUnit : ""}`);
          }
          const suffix = extras.length ? ` <span class="muted">(${escapeHTML(extras.join(", "))})</span>` : "";
          return `<li>${escapeHTML(text)}${suffix}</li>`;
        })
        .join("")}</ol></section>`
    : instructions
      ? `<section><h2>Method</h2><p class="prose">${escapeHTML(instructions)}</p></section>`
      : "";

  const tagsHTML = tags.length
    ? `<p class="tags">${tags.map(tag => `<span>${escapeHTML(tag)}</span>`).join("")}</p>`
    : "";

  const storeHTML = APP_STORE_URL
    ? `<a class="button secondary" href="${escapeHTML(APP_STORE_URL)}">Get Frydge</a>`
    : "";

  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHTML(title)}</title>
  <meta name="description" content="${escapeHTML(description)}">
  <meta property="og:type" content="article">
  <meta property="og:site_name" content="Frydge">
  <meta property="og:title" content="${escapeHTML(title)}">
  <meta property="og:description" content="${escapeHTML(description)}">
  <meta property="og:url" content="${escapeHTML(pageURL)}">
  <meta property="og:image" content="${escapeHTML(imageURL)}">
  <meta property="og:image:width" content="${imageWidth}">
  <meta property="og:image:height" content="${imageHeight}">
  <meta name="twitter:card" content="summary_large_image">
  <meta name="twitter:title" content="${escapeHTML(title)}">
  <meta name="twitter:description" content="${escapeHTML(description)}">
  <meta name="twitter:image" content="${escapeHTML(imageURL)}">
  <meta name="apple-itunes-app" content="app-argument=${escapeHTML(appURL)}">
  <style>
    :root { color-scheme: light dark; }
    body { margin: 0; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; background: #f6f8f4; color: #1d2a1f; }
    @media (prefers-color-scheme: dark) { body { background: #10150f; color: #e9efe6; } .card { background: #1a2219 !important; } }
    main { max-width: 680px; margin: 0 auto; padding: 24px 20px 64px; }
    .card { background: #fff; border-radius: 20px; padding: 20px; box-shadow: 0 10px 30px rgba(0,0,0,0.08); }
    img.hero { width: 100%; border-radius: 14px; display: block; }
    h1 { font-size: 28px; margin: 18px 0 6px; }
    h2 { font-size: 18px; margin: 24px 0 8px; }
    .meta, .muted { color: #6b7a6c; }
    .tags span { display: inline-block; margin: 6px 6px 0 0; padding: 4px 10px; border-radius: 999px; background: rgba(76,140,90,0.14); font-size: 13px; }
    ul, ol { padding-left: 22px; line-height: 1.55; }
    li { margin: 6px 0; }
    .prose { white-space: pre-wrap; line-height: 1.55; }
    .actions { display: flex; gap: 10px; flex-wrap: wrap; margin-top: 22px; }
    .button { display: inline-block; padding: 12px 18px; border-radius: 12px; background: #2f7d46; color: #fff; text-decoration: none; font-weight: 600; }
    .button.secondary { background: rgba(47,125,70,0.12); color: #2f7d46; }
    footer { margin-top: 28px; font-size: 13px; color: #6b7a6c; text-align: center; }
  </style>
</head>
<body>
  <main>
    <div class="card">
      <img class="hero" src="${escapeHTML(imageURL)}" alt="">
      <h1>${escapeHTML(title)}</h1>
      ${metaBits.length ? `<p class="meta">${metaBits.join(" · ")}</p>` : `<p class="meta">${escapeHTML(description)}</p>`}
      ${tagsHTML}
      <div class="actions">
        <a class="button" href="${escapeHTML(appURL)}">Open in Frydge</a>
        ${storeHTML}
      </div>
      ${ingredientsHTML}
      ${stepsHTML}
    </div>
    <footer>Shared from Frydge · cook from what's in your fridge</footer>
  </main>
</body>
</html>`;
}

function formatDuration(totalSeconds) {
  const s = Math.max(0, Math.floor(totalSeconds));
  const h = Math.floor(s / 3600);
  const m = Math.floor((s % 3600) / 60);
  if (h > 0) return m > 0 ? `${h}h ${m}m` : `${h}h`;
  if (m > 0) return `${m}m`;
  return `${s}s`;
}
async function recipeImageResponse(imageKey, env) {
  if (!env.RECIPE_IMAGES) {
    return new Response("Missing RECIPE_IMAGES binding", { status: 500 });
  }

  const cleanKey = cleanId(imageKey);
  if (!cleanKey) {
    return new Response("Invalid image key", { status: 400 });
  }

  const imageBase64 = await env.RECIPE_IMAGES.get(cleanKey);
  if (!imageBase64) {
    return defaultRecipeImageResponse();
  }

  const bytes = Uint8Array.from(atob(imageBase64), char => char.charCodeAt(0));
  return new Response(bytes, {
    headers: {
      "content-type": "image/jpeg",
      "cache-control": "public, max-age=31536000, immutable"
    }
  });
}

function defaultRecipeImageResponse() {
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="630" viewBox="0 0 1200 630">
  <defs>
    <linearGradient id="bg" x1="0" x2="1" y1="0" y2="1">
      <stop offset="0" stop-color="#f7faf4"/>
      <stop offset="1" stop-color="#dfeeda"/>
    </linearGradient>
  </defs>
  <rect width="1200" height="630" fill="url(#bg)"/>
  <circle cx="250" cy="182" r="86" fill="#9cc78a"/>
  <circle cx="920" cy="448" r="118" fill="#f6b36f"/>
  <rect x="320" y="190" width="560" height="250" rx="38" fill="#ffffff" opacity="0.86"/>
  <text x="600" y="305" text-anchor="middle" font-family="-apple-system,BlinkMacSystemFont,Segoe UI,sans-serif" font-size="70" font-weight="700" fill="#243524">Frydge</text>
  <text x="600" y="374" text-anchor="middle" font-family="-apple-system,BlinkMacSystemFont,Segoe UI,sans-serif" font-size="34" fill="#536454">Open this recipe in the app</text>
</svg>`;

  return new Response(svg, {
    headers: {
      "content-type": "image/svg+xml; charset=utf-8",
      "cache-control": "public, max-age=31536000, immutable"
    }
  });
}

async function loadRecipeShare(recipeId, env) {
  if (!env.RECIPE_SHARES) {
    return null;
  }

  const raw = await env.RECIPE_SHARES.get(recipeId);
  if (!raw) {
    return null;
  }

  try {
    return JSON.parse(raw);
  } catch {
    return null;
  }
}

function jsonResponse(value, status = 200, cacheControl = "public, max-age=3600") {
  return new Response(JSON.stringify(value), {
    status,
    headers: {
      "content-type": "application/json; charset=utf-8",
      "cache-control": cacheControl,
      ...corsHeaders()
    }
  });
}

function corsResponse(value, status = 200) {
  return new Response(value, {
    status,
    headers: corsHeaders()
  });
}

function corsHeaders() {
  return {
    "access-control-allow-origin": "*",
    "access-control-allow-methods": "GET,POST,OPTIONS",
    "access-control-allow-headers": "content-type,x-frydge-upload-key"
  };
}

function shouldServeRichPreview(request) {
  const userAgent = request.headers.get("user-agent") || "";
  return PREVIEW_USER_AGENT_PATTERN.test(userAgent);
}

function cleanId(value) {
  if (typeof value !== "string") {
    return "";
  }

  return value.trim().replace(/[^a-zA-Z0-9_-]/g, "").slice(0, 160);
}

function escapeHTML(value) {
  return String(value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}
